-- ============================================
-- LUMA — Thème 12 : MOYEN 2/3 x4 — Une discussion avec un conservateur passionné
-- ============================================


update scenarios set content = '{"characters": {"curator": "le conservateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "curator", "text": "(Notices you lingering) Ah, this piece catches most people''s attention. Care for some insider details?", "text_fr": "(Remarque que vous vous attardez) Ah, cette pièce attire l''attention de la plupart des gens. Ça vous dit des détails d''initié ?", "choices": [{"text": "Absolutely, I''d love to hear more!", "text_fr": "Absolument, j''adorerais en savoir plus !", "next": "n2"}, {"text": "Are you a curator here? That sounds like a fascinating job.", "text_fr": "Vous êtes conservateur ici ? Ça a l''air d''un travail fascinant.", "next": "n2b"}]}, "n2": {"speaker": "curator", "text": "This vase was almost lost forever — it survived a shipwreck and sat underwater for two centuries.", "text_fr": "Ce vase a failli être perdu à jamais — il a survécu à un naufrage et est resté sous l''eau pendant deux siècles.", "choices": [{"text": "That''s incredible! How was it eventually recovered?", "text_fr": "C''est incroyable ! Comment a-t-il finalement été récupéré ?", "next": "n3"}]}, "n2b": {"speaker": "curator", "text": "It is! I''ve been the curator here for fifteen years, and I still discover new stories.", "text_fr": "Ça l''est ! Je suis conservateur ici depuis quinze ans, et je découvre encore de nouvelles histoires.", "choices": [{"text": "Fifteen years, that''s impressive dedication.", "text_fr": "Quinze ans, c''est un dévouement impressionnant.", "next": "n3"}]}, "n3": {"speaker": "curator", "text": "A team of marine archaeologists found it purely by chance, during an unrelated expedition.", "text_fr": "Une équipe d''archéologues marins l''a trouvé purement par hasard, pendant une expédition sans rapport.", "choices": [{"text": "What a stroke of luck for history! Do you have other stories like this?", "text_fr": "Quel coup de chance pour l''histoire ! Vous avez d''autres histoires comme ça ?", "next": "n4"}]}, "n4": {"speaker": "curator", "text": "Oh, dozens! Each piece in this museum has a story most visitors never hear.", "text_fr": "Oh, des dizaines ! Chaque pièce de ce musée a une histoire que la plupart des visiteurs n''entendent jamais.", "choices": [{"text": "I''d love to hear about another one, if you have time.", "text_fr": "J''aimerais en entendre une autre, si vous avez le temps.", "next": "n5"}, {"text": "This makes me want to come back and explore everything more deeply.", "text_fr": "Ça me donne envie de revenir et d''explorer tout plus en profondeur.", "next": "n5b"}]}, "n5": {"speaker": "curator", "text": "There''s a small statue in the next room with quite the scandalous history, actually.", "text_fr": "Il y a une petite statue dans la prochaine salle avec une histoire assez scandaleuse, en fait.", "choices": [{"text": "Now I have to hear this one!", "text_fr": "Maintenant je dois entendre celle-là !", "next": "n6"}]}, "n5b": {"speaker": "curator", "text": "That''s exactly the reaction I love to see. Museums reward curiosity endlessly.", "text_fr": "C''est exactement la réaction que j''aime voir. Les musées récompensent la curiosité sans fin.", "choices": [{"text": "You''ve definitely sparked that curiosity in me today.", "text_fr": "Vous avez définitivement suscité cette curiosité en moi aujourd''hui.", "next": "n6"}]}, "n6": {"speaker": "curator", "text": "(Leads you to the statue) This one was once thought to be a forgery for nearly a century!", "text_fr": "(Vous mène à la statue) Celle-ci a été considérée comme un faux pendant près d''un siècle !", "choices": [{"text": "How did they eventually prove it was authentic?", "text_fr": "Comment ont-ils fini par prouver qu''elle était authentique ?", "next": "n7"}]}, "n7": {"speaker": "curator", "text": "Modern dating techniques finally confirmed its true age, correcting decades of assumption.", "text_fr": "Des techniques de datation modernes ont finalement confirmé son vrai âge, corrigeant des décennies de suppositions.", "choices": [{"text": "Science rewriting history — that''s amazing.", "text_fr": "La science qui réécrit l''histoire — c''est incroyable.", "next": "n8"}]}, "n8": {"speaker": "curator", "text": "Exactly! This is why I never tire of this work — there''s always more to uncover.", "text_fr": "Exactement ! C''est pour ça que je ne me lasse jamais de ce travail — il y a toujours plus à découvrir.", "choices": [{"text": "Thank you so much for sharing all of this with me today.", "text_fr": "Merci beaucoup d''avoir partagé tout ça avec moi aujourd''hui.", "next": "end_passionate"}]}, "end_passionate": {"speaker": "curator", "text": "It''s rare to find visitors this engaged. Come back anytime, I always have more stories!", "text_fr": "C''est rare de trouver des visiteurs aussi engagés. Revenez quand vous voulez, j''ai toujours plus d''histoires !", "end": true, "ending_label": "Anecdotes exclusives partagées avec passion 🏛️📜"}}}'::jsonb, is_playable = true
where title = 'Une discussion avec un conservateur passionné'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
